SELECT if(user_email != '', user_email, hook_hostname) AS group_value, sumIfMerge(total_cost) AS m_cost_usd, sumIfMerge(total_input_tokens) AS m_input_tokens, sumIfMerge(total_output_tokens) AS m_output_tokens, sumIfMerge(total_tokens) AS m_tokens_total, sumIfMerge(cache_read_input_tokens) AS m_cache_read_tokens, sumIfMerge(cache_creation_input_tokens) AS m_cache_write_tokens, if(uniqExactIfMerge(unique_tool_calls) = 0, countIfMerge(total_tool_calls), uniqExactIfMerge(unique_tool_calls)) AS m_tool_calls, uniqExactIfMerge(total_chats) AS m_chats, sumIfMerge(total_work_units) AS m_total_work_units, sumIfMerge(scored_cost) AS m_scored_cost, sumIfMerge(scored_tokens) AS m_scored_tokens, map('account_type', groupUniqArray(1000)(account_type), 'billing_mode', groupUniqArray(1000)(billing_mode), 'cost_center', groupUniqArray(1000)(cost_center_name), 'department', groupUniqArray(1000)(department_name), 'division', groupUniqArray(1000)(division_name), 'employee_type', groupUniqArray(1000)(employee_type), 'group', arrayDistinct(arrayConcat(groupUniqArrayArray(1000)(groups), if(countIf(empty(groups)) > 0, [''], []))), 'hostname', groupUniqArray(1000)(hook_hostname), 'job_title', groupUniqArray(1000)(job_title), 'mcp_server', arrayFilter(x -> x != '', groupUniqArray(1000)(mcp_server_name)), 'mcp_tool', arrayFilter(x -> x != '', groupUniqArray(1000)(mcp_tool_name)), 'model', groupUniqArray(1000)(model), 'project', groupUniqArray(1000)(toString(gram_project_id)), 'provider', groupUniqArray(1000)(provider), 'query_source', arrayFilter(x -> x != '', groupUniqArray(1000)(query_source)), 'role', arrayDistinct(arrayConcat(groupUniqArrayArray(1000)(roles), if(countIf(empty(roles)) > 0, [''], []))), 'skill', arrayFilter(x -> x != '', groupUniqArray(1000)(skill_name)), 'subagent', arrayFilter(x -> x != '', groupUniqArray(1000)(agent_name)), 'surface', groupUniqArray(1000)(hook_source)) AS dimension_values FROM attribute_metrics_summaries WHERE is_active = 1 AND gram_project_id IN (?) AND time_bucket >= toStartOfHour(fromUnixTimestamp64Nano(?)) AND time_bucket <= toStartOfHour(fromUnixTimestamp64Nano(?)) GROUP BY group_value ORDER BY m_cost_usd DESC
